	"encoding/json"
	"errors"
)

type Item struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

type ItemsPage struct {
	Items      []Item `json:"items"`
	NextCursor *string `json:"next_cursor"`
}

type ItemsRequest struct {
	Path   string
	Limit  int
	Cursor *string
}

type ItemsFetcher func(ItemsRequest) ([]byte, error)

// ConsumeItems validates and normalizes one structured GET /items response.
func ConsumeItems(body string) string {
	var page ItemsPage
	if err := json.Unmarshal([]byte(body), &page); err != nil {
		return `{"items":[],"next_cursor":null}`
	}
	normalized, err := json.Marshal(page)
	if err != nil {
		return `{"items":[],"next_cursor":null}`
	}
	return string(normalized)
}

