func FetchAllItems(fetch ItemsFetcher, limit int) ([]Item, error) {
	if fetch == nil {
		return nil, errors.New("items fetcher is required")
	}
	if limit < 1 {
		return nil, errors.New("limit must be at least 1")
	}

	items := make([]Item, 0)
	var cursor *string // the initial request deliberately sends cursor=null
	for {
		raw, err := fetch(ItemsRequest{
			Path:   "/items",
			Limit:  limit,
			Cursor: cursor,
		})
		if err != nil {
			return nil, err
		}

